0: // Auto
  if OCCUPANCY_DETECTED then
    TEMP_SETPOINT_ADJUST := 0;
  else
    if ENERGY_SAVING_MODE then
      TEMP_SETPOINT_ADJUST := 3;
    else
      TEMP_SETPOINT_ADJUST := 2;
    end_if;
  end_if;
1: // Comfort
  if OCCUPANCY_DETECTED then
    TEMP_SETPOINT_ADJUST := 0;
  else
    TEMP_SETPOINT_ADJUST := 1;
  end_if;
2: // Economy
  if OCCUPANCY_DETECTED then
    TEMP_SETPOINT_ADJUST := 0;
  else
    TEMP_SETPOINT_ADJUST := 4;
  end_if;
3: // Night
  TEMP_SETPOINT_ADJUST := 4;
end_case;

Note: Must keep TEMP_SETPOINT_ADJUST within ±4°C. So the above values are within that range. The logic does not need to clamp; it's always within range. Also note that negative adjustments are not used.

Now need to define the timer. In ST we can instantiate a TON function block:

VAR
